    final Attribute stringAttr = new Attribute("stringAttr", stringDatatype, new long[] { 1L });
    stringAttr.setValue(new String[] { "bla", "blubb", "lalala" });
    final String stringAttrValue = ProbaVUtils.getAttributeValue(stringAttr);
    <extra_id_0>
}

